const inputData = $('Execute Workflow Trigger').first()?.json || {};
const filtroBodega = (inputData.bodega || 'TODAS').trim().toLowerCase();

const inventarios = $('Obtener Inventario').all().map(i => i.json);
const bodegas = $('Obtener Bodegas').all().map(i => i.json);
const productos = $('Obtener Productos').all().map(i => i.json);

const bodegaMap = new Map(bodegas.map(b => [b.id_bodega, b]));
const prodMap = new Map(productos.map(p => [p.id_producto, p]));

const grupos = new Map();

for (const inv of inventarios) {
  if (Number(inv.cantidad_almacenada) <= 0 || inv.fecha_salida) continue;
  const b = bodegaMap.get(inv.id_bodega);
  if (!b) continue;

  if (filtroBodega !== 'todas') {
    const matchCodigo = b.codigo_bodega.toLowerCase() === filtroBodega;
    const matchNombre = b.nombre.toLowerCase().includes(filtroBodega);
    if (!matchCodigo && !matchNombre) continue;
  }

  const p = prodMap.get(inv.id_producto);
  if (!p) continue;

  const key = inv.id_bodega + '_' + inv.id_producto + '_' + inv.unidad_medida;
  if (!grupos.has(key)) {
    grupos.set(key, {
      nombre_bodega: b.nombre,
      codigo_bodega: b.codigo_bodega,
      producto: p.nombre_comercial,
      sku: p.codigo_sku,
      total_existencia: 0,
      unidad_medida: inv.unidad_medida,
      posiciones_estante_ocupadas: 0
    });
  }

  const g = grupos.get(key);
  g.total_existencia += Number(inv.cantidad_almacenada);
  g.posiciones_estante_ocupadas++;
}

const resultados = Array.from(grupos.values())
  .map(g => ({ ...g, total_existencia: Math.round(g.total_existencia * 100) / 100 }))
  .sort((a, b) => a.nombre_bodega.localeCompare(b.nombre_bodega) || a.producto.localeCompare(b.producto) || a.unidad_medida.localeCompare(b.unidad_medida));

return [{
  json: {
    estado: 'exitoso',
    herramienta: 'consultar_stock_por_bodega',
    filtros: { bodega: inputData.bodega || 'TODAS' },
    total_registros: resultados.length,
    es_parcial: false,
    datos: resultados
  }
}];
